toolArgs.file_text:
.step-indicator {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    counter-reset: step;
}

.step-item {
    flex: 1;
    text-align: center;
    position: relative;
    padding-top: 2.5rem;
}

.step-item::before {
    content: "";
    position: absolute;
    top: 1rem;
    left: 0;
    right: 0;
    height: 3px;
    background: #dee2e6;
    z-index: 0;
}

.step-item:first-child::before {
    left: 50%;
}

.step-item:last-child::before {
    right: 50%;
}

.step-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background: #dee2e6;
    color: #6c757d;
    font-weight: 600;
    font-size: 0.875rem;
    position: relative;
    z-index: 1;
}

.step-label {
    display: block;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    color: #6c757d;
}

.step-item.active .step-number {
    background: #0d6efd;
    color: white;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-number {
    background: #198754;
    color: white;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-item.completed:not(.active) {
    cursor: pointer;
}

.step-item.completed:not(.active):hover .step-number {
    transform: scale(1.1);
    transition: transform 0.15s;
}

.step-item.dimmed .step-label {
    color: #adb5bd;
}

.step-item.dimmed .step-number {
    background: #e9ecef;
    color: #adb5bd;
}

