toolArgs.file_text:
@* Single work history entry form *@

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-start mb-2">
            <h6 class="card-title mb-0">Position @Index</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Entry.Company" @bind:event="oninput" placeholder="Company name" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Entry.Title" @bind:event="oninput" placeholder="Job title" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" @bind="Entry.StartDate" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input type="checkbox" class="form-check-input" id="@_currentId" @bind="Entry.IsCurrent"
                           @onclick="HandleCurrentToggle" />
                    <label class="form-check-label" for="@_currentId">I currently work here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" @bind="Entry.Description" @bind:event="oninput"
                          placeholder="Describe your responsibilities and achievements"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private readonly string _currentId = $"current-{Guid.NewGuid():N}";

    private void HandleCurrentToggle()
    {
        if (!Entry.IsCurrent)
        {
            // Will become checked — clear end date
            Entry.EndDate = null;
        }
    }
}

@* Step 1: Personal information *@

<h4 class="mb-4">Personal Information</h4>

@if (!string.IsNullOrEmpty(_error))
{
    <div class="alert alert-danger">@_error</div>
}

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input class="form-control @ValidationClass(Model.FullName)" @bind="Model.FullName" @bind:event="oninput"
               placeholder="John Doe" />
        @if (_attempted && string.IsNullOrWhiteSpace(Model.FullName))
        {
            <div class="invalid-feedback d-block">Full name is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control @ValidationClass(Model.Email)" @bind="Model.Email" @bind:event="oninput"
               placeholder="john@example.com" />
        @if (_attempted && string.IsNullOrWhiteSpace(Model.Email))
        {
            <div class="invalid-feedback d-block">Email is required.</div>
        }
        else if (_emailInvalid)
        {
            <div class="invalid-feedback d-block">This email address could not be validated.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control @ValidationClass(Model.Phone)" @bind="Model.Phone" @bind:event="oninput"
               placeholder="(555) 123-4567" />
        @if (_attempted && string.IsNullOrWhiteSpace(Model.Phone))
        {
            <div class="invalid-feedback d-block">Phone number is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input class="form-control @ValidationClass(Model.Address)" @bind="Model.Address" @bind:event="oninput"
               placeholder="123 Main St, City, State" />
        @if (_attempted && string.IsNullOrWhiteSpace(Model.Address))
        {
            <div class="invalid-feedback d-block">Address is required.</div>
        }
    </div>
</div>

<div class="d-flex justify-content-end mt-4">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@_validating">
        @if (_validating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private bool _attempted;
    private bool _validating;
    private bool _emailInvalid;
    private string? _error;

    private string ValidationClass(string value) =>
        _attempted ? (string.IsNullOrWhiteSpace(value) ? "is-invalid" : "is-valid") : "";

    private async Task HandleNext()
    {
        _attempted = true;
        _emailInvalid = false;
        _error = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            return;
        }

        _validating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!emailValid)
            {
                _emailInvalid = true;
                return;
            }
            await OnNext.InvokeAsync();
        }
        catch (Exception ex)
        {
            _error = $"Validation failed: {ex.Message}";
        }
        finally
        {
            _validating = false;
        }
    }
}

