    private bool _isSubmitting;
    private int? _applicationId;

    private void GoToStep(int step)
    {
        if (step >= 0 && step < _stepNames.Count)
        {
            _currentStep = step;
        }
    }

    private void CompleteAndAdvance(int step)
    {
        _completedSteps.Add(step);
        _currentStep = step + 1;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        try
        {
            var application = new JobApplication(
                new PersonalInfo(_personal.FullName, _personal.Email, _personal.Phone, _personal.Address),
                new WorkHistory(_workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate!.Value, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                _references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _completedSteps.Add(4);
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

